  "name": "string",
  "ledSettings": {
    "isEnabled": true
  }
});


let config = {
  method: 'patch',
  maxBodyLength: Infinity,
  url: 'https://192.168.0.1/proxy/protect/integration/v1/relays/{id}',
  headers: { 
    'Accept': 'application/json', 
    'X-API-Key': '<X-API-Key>', 
    'Content-Type': 'application/json'
  },
  data : data
};


