import http.client
import json


conn = http.client.HTTPSConnection("192.168.0.1")
payload = json.dumps({
  "name": "string",
  "ledSettings": {
    "isEnabled": True
  }
})
headers = {
  'Accept': 'application/json',
  'X-API-Key': '<X-API-Key>',
  'Content-Type': 'application/json'
}
conn.request("PATCH", "/proxy/protect/integration/v1/relays/{id}", payload, headers)
res = conn.getresponse()
data = res.read()
print(data.decode("utf-8"))

